        private static readonly System.Collections.Generic.Dictionary<(short, short), string> Chunks = new System.Collections.Generic.Dictionary<(short, short), string> {
            { ((short)29, (short)0), "A MANGLED PAGE OF FINE\rPAPER WITH ENTRIES WRITTEN\rIN A VERY FINE HAND.\r\r\"HE IS LIVID ABOUT THE\rUNDEAD COMING OUT OF\rVALHINGEN GRAVEYARD. THREE\rTIMES HE HAS SENT ASSAULT\rGROUPS, THREE TIMES NONE" },
            { ((short)29, (short)1), "HAVE RETURNED. HE DARES NOT\rSEND ANY OF THE PRIESTS OF\rBANE TO CLEAR THE\rGRAVEYARD. HE ASSUMES THAT\rIF A PRIEST COULD WREST\rCONTROL OF THE UNDEAD FROM\rTHEIR CURRENT MASTER, THAT\rTHE PRIEST WOULD THEN\rBECOME A THREAT TO HIS" },
            { ((short)29, (short)2), "POWER.\r\r\"I SUGGESTED THAT IF WE\rCOULD NEUTRALIZE THE POWER\rTHAT LEADS THE UNDEAD, THAT\rWE COULD THEN USE THE\rUNDEAD AS A TOOL. HE\rTHOUGHT ON THIS AND THEN\rORDERED ME TO FIND OUT WHO" },
            { ((short)29, (short)3), "OR WHAT IS IN CONTROL IN\rVALHINGEN GRAVEYARD.\rPRELIMINARY INVESTIGATION\rSHOWS THAT THE GRAVEYARD IS\rCONTROLLED BY A BEING OF\rGREAT POWER, PERHAPS A\rVAMPIRE OR A DEMON. I SHALL\rEXPEND A FEW SCOUTS AND LOW\rLEVEL PRIESTS TO FIND OUT" },
            { ((short)29, (short)4), "MORE INFORMATION.\"" },
            { ((short)30, (short)0), "MESSAGE SCRATCHED INTO THE\rWALL OVER THE POOL.\r\rBEWARE THE POWER OF THE\rPOOL.\rDEATH TO THOSE UNWORTHY OF\rTHE GIFTS OF THE POOL.\rPOWER TO THOSE WHO WILL USE\rTHE GIFTS OF THE POOL" },
            { ((short)30, (short)1), "WISELY.\rBATHE IN THE POOL IF YOU\rDARE." },
            { ((short)31, (short)0), "A FLOWERY NOTE WRITTEN ON\rSTATIONARY EMBLAZONED WITH\rTHE SYMBOL OF THE CITY\rCOUNCIL OF NEW PHLAN.\r\r\"WITH THE ARTIFACT AND\rAGREEMENT IN THIS POUCH WE\rHAVE MADE OUR FINAL\rCONCESSIONS TO YOUR" },
            { ((short)31, (short)1), "DEMANDS. WE HAVE GIVEN YOU\rEVERYTHING YOU HAVE ASKED\rFOR. THIS SHOULD SETTLE OUR\rDIFFERENCES AND CEMENT OUR\rALLIANCE.\r\r\"NOW THAT WE HAVE DELIVERED\rOUR PART OF THE BARGAIN WE\rWILL EXPECT YOU TO UPHOLD" },
            { ((short)31, (short)2), "YOUR END. USE THIS\rPROTECTED POUCH AND OUR\rREPRESENTATIVES TO DELIVER\rYOUR PART OF THE BARGAIN TO\rTHE CITY COUNCIL. REMEMBER\rTO INCLUDE ALL OF THE\rMAGICAL ITEMS WE AGREED\rUPON.\r" },
            { ((short)31, (short)3), "\"WITH THE BURIED RICHES IN\rTHE RECLAIMED PHLAN, AND\rTHE MIGHT OF ZHENTIL KEEP\rWE WILL BE ABLE TO CONTROL\rALL OF THE NORTHERN SHORES\rOF THE MOONSEA.\"\r\rSIGNED\rPORPHYRYS CADORNA" },
            { ((short)31, (short)4), "CITY COUNCIL\rNEW PHLAN" },
            { ((short)32, (short)0), "SEVERAL PIECES OF PAPER\rWITH HIGHLY ORGANIZED\rWRITING.\r\rFACT: PORPHYRYS CADORNA IS\rTHE LAST KNOWN SURVIVING\rMEMBER OF THE CADORNA CLAN.\r\rSTRONG RUMOR: RISING STAR" },
            { ((short)32, (short)1), "IN CITY POLITICS AND ON THE\rCITY COUNCIL.\r\rRUMOR: VERY CHARMING, HAS\rMANY ADMIRERS, BUT NO KNOWN\rMATE.\r\rRUMOR: VINDICTIVE, LIKES TO\rGET HIS OWN WAY AND" },
            { ((short)32, (short)2), "REMEMBERS WHEN HE IS (IN\rHIS MIND) DOUBLE CROSSED.\r\rFACT: HAS CONTACTED THIEVES\rTO HAVE THEM GAIN HIM\rINFORMATION ON THE POOL OF\rRADIANCE.\r\rFACT: HAS HIRED A NUMBER OF" },
            { ((short)32, (short)3), "MERCENARIES THROUGH THE\rTHIEVES (WE RECEIVED OUR\rNORMAL CUT).\r\rVAGUE RUMOR: IS USING\rMERCENARIES TO FIND POOL OF\rRADIANCE." },
            { ((short)33, (short)0), "A CLEAN MAP DRAWN WITH\rEXACT LINES.\r\r(PICTURE)" },
            { ((short)34, (short)0), "TOLD IN A PROUD, HAUGHTY\rVOICE.\r\r\"I AM A PRINCESS OF A TRIBE\rOF NOMADS TO THE NORTHWEST.\rMY FATHER IS AN OLD FOOL.\rHE WANTED ME TO MARRY KING\rAL RASID, TO CEMENT AN\rALLIANCE. I HAD MORE" },
            { ((short)34, (short)1), "IMPORTANT THINGS TO DO,\rTHAN BE TIED DOWN TO AN\rAGING MONARCH. WHEN I\rMARRY, IT SHALL BE TO\rSOMEONE WHO HAS THE SAME\rTASTE OF ADVENTURE AND THE\rSAME SKILL WITH A SWORD.\r\r\"WELL, FATHER WAS INSISTENT" },
            { ((short)34, (short)2), "AND HIS SUBJECTS SUPPORTED\rHIM, SO I LEFT TO SEEK MY\rFORTUNE. KOBOLDS HAD BEEN\rRAIDING OUR TENTS UPON\rOCCASION, SO I HEADED THIS\rWAY. IF I COULD END THE\rTHREAT, THEN I'D HAVE MORE\rLEVERAGE WITH MY TRIBE.\rHOWEVER, TWO NIGHTS AGO, I" },
            { ((short)34, (short)3), "WAS AMBUSHED BY THESE WORMS\r-- KNOCKED OUT AND BOUND\rUP. I FINALLY GOT MYSELF\rUNTIED A LITTLE WHILE AGO\rAND WAS WORKING MY WAY OUT\rOF THESE CAVES, WHEN YOU\rSHOWED UP.\"" },
            { ((short)35, (short)0), "A QUICK NOTE ON AN OFTEN\rUSED PIECE OF PAPER.\r\r\"I MUST FIND SOME HARDY\rALLIES IN CASE THIS MONSTER\rFROM PHLAN SENDS HIS TROOPS\rTO ATTACK MY ISLAND. I NEED\rA SMALL, INTELLIGENT PARTY\rWHO CAN MOVE THROUGH THE" },
            { ((short)35, (short)1), "CIVILIZED AREAS WITHOUT\rNOTICE, BUT WHO HAVE THE\rSKILL TO TRAVERSE THE\rUNCIVILIZED AREAS AND THE\rWILDERNESS. I MUST WATCH\rTHE NEXT GROUPS TO COME TO\rTHE LAKE AND SEE IF ANY\rWOULD MAKE PROPER ALLIES.\"" },
            { ((short)36, (short)0), "A RATTY PIECE OF PARCHMENT\rWITH LARGE WRITING ON ONE\rSIDE.\r\r\"HOLD THE SOKAL KEEP ON\rTHORN ISLAND AT ALL COSTS.\rIF ATTACKED, SACRIFICE YOUR\rTROOPS AS NECESSARY TO HOLD\rOUT UNTIL RELIEVED." },
            { ((short)36, (short)1), "\r\"IN YOUR DEPLOYMENT SET TWO\rSQUADS OF HOBGOBLINS TO\rPATROL THORN ISLAND AT ALL\rTIMES. AT LEAST 2 SQUADS OF\rARCHERS ARE TO BE DEPLOYED\rON THE WALLS AT ALL TIMES.\rLET THE PACK OF WARDOGS\rLOOSE TO COVER THE ISLAND" },
            { ((short)36, (short)2), "SEVERAL TIMES A DAY AT\rRANDOM INTERVALS. SET PAIRS\rOF KOBOLDS AS OBSERVERS IN\rHIDDEN LOCATIONS AROUND THE\rISLAND.\r\rIF THORN ISLAND IS INVADED\rIMMEDIATELY DISPATCH A\rMESSAGE BACK TO THE CASTLE." },
            { ((short)36, (short)3), "WE WILL SEND OVER HOWEVER\rMANY REINFORCEMENTS ARE\rNECESSARY TO HOLD THE\rISLAND.\"" },
            { ((short)37, (short)0), "A BLACK BOUND TOME WRITTEN\rIN A STRANGE HALTING HAND.\r\r\"...AND SETTLED FOREMOST IN\rTHE HALL OF MINOR COURTIERS\rWERE THE LESSER POWERS:\rMARAM OF THE GREAT SPEAR;\rHAASK, VOICE OF HARGUT;\rTYRANTHRAXUS THE FLAMED" },
            { ((short)37, (short)1), "ONE; BOREM OF THE LAKE OF\rBOILING MUD; AND CAMNOD THE\rUNSEEN. THESE TOO FELL DOWN\rAND BECAME SERVANTS OF THE\rGREAT LORD BANE.\"" },
            { ((short)38, (short)0), "TOLD IN A PAINED VOICE.\r\r\"WE JUST GOT THE CUT\rTHROUGH TO THE BEASTIE'S\rLAIR WHEN I INJURED MY LEG.\rKING DECIDED THERE WASN'T\rMUCH USE FER ME ANYMORE.\rMADE ME A PROPOSITION\rTHOUGH. SAID IF I WENT INTO" },
            { ((short)38, (short)1), "THE LAIR AND BROUGHT OUT\rTHE TREASURE, HE'D FEED ME\rTILL I STOPPED BREATHIN'.\rBEST DEAL I HAD, SO THEY\rTOSSED ME DOWN HERE. NOT\rBEIN' A FOOL, I LIT OUT FOR\rTHE DEEPEST HIDEY-HOLE.\rTHANKFULLY THE BEASTIE WAS\rASLEEP. I CAN STILL MOVE" },
            { ((short)38, (short)2), "REAL QUIET WHEN I MUST.\r\r\"ANYWAY, IF THERE HASN'T\rBEEN MUCH OF AN ALARM, THEN\rDRUNKEN FERD MUST BE ON\rWATCH AT THE ROCK. HE'S THE\rKING'S SON, SO HE AIN'T\rHERE WITH ME -- WORTHLESS\rSOT. IF HE'S THERE, HE'S" },
            { ((short)38, (short)3), "GOT LESS BRAINS THAN A\rFERMENTED RAT, JUST ACT\rOFFICIOUS AND HE'LL TAKE YA\rTA THE KING. WOULDN'T MIND\rHEARIN' OF THAT TYRANT'S\rDEMISE. YA SEEM JUST THE\rTYPES TA DO IT TOO.\"" },
            { ((short)39, (short)0), "A CRUMBLING OLD BOOK; ONE\rOF A MASSIVE SERIES.\r\r\"AT THIS TIME THERE RULING\rTHE TWISTED ONES WAS A\rPOWERFUL GENERAL NAMED\rTYRANTHRAXUS. HE STRODE\rBEFORE HIS ARMIES CLOAKED\rIN FLAME AND LED THE RIDERS" },
            { ((short)39, (short)1), "OUT OF THE WASTE. AT HIS\rHAND THE KINGDOM OF BARZE\rWAS CONQUERED. TURNING\rSOUTH HE LED HIS ARMY TO\rCONQUER THE HORREB AND THE\rVANE. TYRANTHRAXUS WAS A\rCRUEL MAN AND LEVELED ALL\rTHAT HE HAD TAKEN,\rMURDERING THE PRINCES OF" },
            { ((short)39, (short)2), "THESE LANDS. BUT THE FLAME\rTHAT SURROUNDED HIM\rCONSUMED HIM, DESTROYING\rHIS BODY. FREED OF ITS\rSHELL, IT FLEW AMONG THE\rMEN OF HIS ARMY, LIGHTING\rON EACH AND CLAIMING IT. IT\rWAS THEN WHEN BARON SCHODT\rIMPRISONED TYRANTHRAXUS IN" },
            { ((short)39, (short)3), "A VIAL OF WATER WHICH SHONE\rLIKE THE LIGHT OF DAY. THIS\rHE SANK IN THE WATERY\rDEPTHS OF LAKE LONGREACH,\rDEFEATING THE ARMIES\rTYRANTHRAXUS HAD RAISED.\"" },
            { ((short)40, (short)0), "A NEW FOLDED CLOTH MAP\rDRAWN IN WATERPROOF INK.\r\r(PICTURE)" },
            { ((short)41, (short)0), "SEVERAL PIECES OF PAPER\rWITH HIGHLY ORGANIZED\rWRITING.\r\rFACT: ULRICH EBERHARD IS\rOLD, HARD HEADED IN EVERY\rSENSE OF THE WORD, LEADER\rOF THE INITIAL EXPEDITION\rTO RETAKE PHLAN." },
            { ((short)41, (short)1), "\rSTRONG RUMOR: UNFAITHFUL TO\rHIS WIFE, BUT SHE KNOWS,\rTHOUGH HE DOESN'T KNOW SHE\rKNOWS.\r\rRUMOR: HATES MONSTERS, WITH\rA PASSION; WOULD KILL EVERY\rLAST ONE BEFORE" },
            { ((short)41, (short)2), "SURRENDERING.\r\rVAGUE RUMOR: ANGRY ATTITUDE\rIS A COVER; HE IS ACTUALLY\rPAID BY THE BOSS.\r\rRUMOR: OPPOSES RISE OF\rPORPHYRYS CADORNA AS A,\r\"YOUNG UPSTART WHO DOESN'T" },
            { ((short)41, (short)3), "RESPECT HIS ELDERS!\"" },
            { ((short)42, (short)0), "A PIECE OF OLD, EXPENSIVE\rPAPER WRITTEN IN A DRIED\rBROWN FLUID.\r\r\"CURSED IS THE CHILD\rPORPHYRYS. HE WHO WAS\rVISITED BY THE SPIRIT OF\rFIRE IN HIS CRADLE. HE WHO\rBURNED HIS NURSEMAID, AND" },
            { ((short)42, (short)1), "HE WHO CALLED THE ARMIES OF\rTHE NIGHT DOWN FROM THE\rMOUNTAINS.\r\r\"POSSESSED IS THE ONE\rCALLED PORPHYRYS. WHEN THE\rSPIRIT OF EVIL IS IN HIM\rYOU CAN SEE THE FIRE IN HIS\rEYES. WHEN HE IS POSSESSED," },
            { ((short)42, (short)2), "THE GROUND TREMBLES WITH\rHIS POWER AND THE NEARBY\rPLANTS WITHER AS IF EXPOSED\rTO A GREAT HEAT.\r\r\"NONE OF THE SERVANTS WILL\rGO NEAR THE CHILD ANY MORE.\rI THINK HE SHOULD HAVE BEEN\rDROWNED AT BIRTH. BUT HIS" },
            { ((short)42, (short)3), "MOTHER IS BLIND TO HIS\rPOSSESSION. SHE GUARDS HIM\rLIKE A TIGRESS PROTECTING A\rKITTEN. I THINK HE HAS\rENSORCERED HER.\r\r\"FOR NOW WE HAVE NO CHOICE.\rWE WILL EVACUATE THE CITY\rBY SHIP ON THE MORROW. AND" },
            { ((short)42, (short)4), "THE ACCURSED CHILD SHALL\rCOME ALONG. I SWEAR THAT HE\rSMILES EVERY TIME THERE IS\rAN EXPLOSION, OR ANYTIME\rYOU HEAR A MAN SCREAM.\rSAINTS PRESERVE US ALL FROM\rTHIS DEMON CHILD.\"" },
            { ((short)43, (short)0), "AN OFFICIAL-LOOKING NOTICE.\r\r\"THE NUMBER OF UNDEAD\rCREEPING OUT OF THE\rVALHINGEN GRAVEYARD IS\rINCREASING. THESE UNDEAD\rHAVE DISRUPTED TRAINING,\rDESTROYED PROPERTY, AND\rKILLED MANY OF OUR TROOPS." },
            { ((short)43, (short)1), "PATROLS HAVE BEEN SENT INTO\rTHE GRAVEYARD TO\rRECONNOITER AND DETERMINE\rTHE SOURCE OF THE UNDEAD.\rNONE HAVE RETURNED. UNDER\rYOUR RESPONSIBILITIES AS A\rPRIEST OF BANE IN THE CITY,\rYOU MUST HELP COMBAT THE\rMENACE." },
            { ((short)43, (short)2), "\r\"LEAD A GROUP OF ACOLYTES\rINTO THE GRAVEYARD WITH THE\rPURPOSE OF DISCOVERING THE\rSOURCE AND LEADER OF THE\rUNDEAD. IF YOUR GROUP CAN\rENGAGE AND DEFEAT THE\rLEADER, OR DESTROY THE\rSOURCE, DO SO. IF YOUR" },
            { ((short)43, (short)3), "GROUP IS OUTMATCHED, RETURN\rWITH YOUR INFORMATION SO\rTHAT WE CAN FORM AN ASSAULT\rGROUP WITH CLERICS AND\rTROOPS. UPON COMPLETION OF\rTHIS MISSION YOU WILL BE IN\rLINE FOR PROMOTION TO THE\rNEXT HIGHER RANK IN THE\rHIERARCHY OF THE TEMPLE OF" },
            { ((short)43, (short)4), "BANE IN PHLAN.\"\r\rSIGNED\rTHE BOSS" },
            { ((short)44, (short)0), "A SMALL BOUND BOOK.\r\r\"I HAVE CHARTED THIS MAZE\rAS CLOSELY AS I CAN. MY WAY\rIS BLOCKED BY BOTH STONE\rAND MYSTIC DEATH TRAPS.\rYARASH MUST HAVE USED HIS\rMAGIC TO ESCAPE THIS PLACE.\rI CAN FIND NO OTHER WAY" },
            { ((short)44, (short)1), "OUT.\"\r\r(PICTURE: MAP)\r\r\"YARASH HAS BEEN BREEDING\rCREATURES FOR INCREASED\rFEROCITY. MOST OF HIS\rEXPERIMENTS FAIL. FEW LIVE\rLONG ENOUGH TO MATURE. NONE" },
            { ((short)44, (short)2), "THAT MATURE HAVE YET BRED\rTRUE. THE BODIES OF HIS\rFAILURES ARE OFTEN USED AS\rFOOD FOR HIS NEWER\rCREATIONS.\r\r\"I DO NOT KNOW WHAT YARASH\rINTENDS TO DO WHEN HE\rCOMPLETES HIS HIDEOUS" },
            { ((short)44, (short)3), "EXPERIMENTS. BUT I MUST\rASSUME THAT HE WILL TURN\rHIS ABOMINATIONS LOOSE ON\rTHE WORLD. TO THESE\rCREATURES YARASH WILL BE\rTHEIR CREATOR, PERHAPS EVEN\rTHEIR GOD! THE IDEA OF\rYARASH AS A GOD TO ANYONE\rSICKENS ME. I MUST FIND A" },
            { ((short)44, (short)4), "WAY TO STOP HIM." },
            { ((short)45, (short)0), "AN IMPRESSIVE ANNOUNCEMENT.\r\r\"BOUNTY OF 10,000 GOLD!\r\r\"I WILL PAY 10,000 GOLD\rPIECES FOR A LIVE SAHUAGIN!\rI WILL PAY 1,000 GOLD\rPIECES FOR A RECENTLY DEAD\rSAHUAGIN IN GOOD CONDITION." },
            { ((short)45, (short)1), "I NEED A SPECIMEN OF THIS\rMAN-LIKE SALT WATER AQUATIC\rCREATURE FOR MY STUDIES.\r\r\"BRING YOUR SPECIMEN TO THE\rSHORE OF LAKE KUTO AND\rBUILD A FIRE AS A SIGNAL.\rYOUR SPECIMEN WILL BE\rEXAMINED. IF IT IS TRULY A" },
            { ((short)45, (short)2), "SAHUAGIN YOU COULD END UP\rWITH 10,000 GOLD PIECES.\rBUT BEWARE, I WILL KNOW ANY\rFORGERIES, AND I WILL\rPUNISH ANY ATTEMPT AT\rDECEPTION.\r\r\"SO, CAPTURE A LIVE\rSAHUAGIN, BRING HIM TO LAKE" },
            { ((short)45, (short)3), "KUTO, AND WALK AWAY A RICH\rMAN!\"\r\rSIGNED\rYARASH THE SORCERER" },
            { ((short)46, (short)0), "A CRUDE MAP BURNED INTO AN\rANIMAL SKIN.\r\r(PICTURE)" },
            { ((short)47, (short)0), "A CLEAN MAP DRAWN WITH\rEXACT LINES.\r\r(PICTURE)" },
            { ((short)48, (short)0), "CAREFULLY PREPARED NOTES.\r\rNOTE 1: \"TYRANTHRAXUS IS\rDEFINITELY A PRODUCT OF\rIMMERSION IN THE POOL OF\rRADIANCE. HIS EXTRAORDINARY\rBRILLIANCE, VIGOR,\rCHARISMA, AND POWER OF\rCOMMAND MUST BE A DIRECT" },
            { ((short)48, (short)1), "RESULT OF EXPOSURE TO THE\rEFFECTS OF THE POOL.\"\r\rNOTE 2: \"THE POOL OF\rRADIANCE MAY GRANT SPECIAL\rMAGICAL ABILITIES.\rTYRANTHRAXUS EXHIBITS A\rFIERY AURA, OBVIOUSLY\rMAGICAL. HE ALSO SEEMS TO" },
            { ((short)48, (short)2), "HAVE EXTRAORDINARY MEANS OF\rOBTAINING INFORMATION.\rSPECIAL MAGICAL POWERS\rGRANTED BY THE POOL WOULD\rEXPLAIN BOTH THE AURA AND\rTHE EXTRA INFORMATION\rGATHERING CAPABILITY.\"\r\rNOTE 3: \"TYRANTHRAXUS TELLS" },
            { ((short)48, (short)3), "STORIES ABOUT MOVING DOWN\rFROM THE NORTH. THOUGH HE\rNEVER MENTIONS THE POOL, I\rGATHER THAT IT IS NORTHWEST\rOF THE DRAGONSPINE\rMOUNTAINS. STRANGELY, HE\rOCCASIONALLY LETS SLIP THAT\rHE IS NEVER FAR FROM THE\rPOOL, BUT THAT MUST BE A" },
            { ((short)48, (short)4), "PARENTHETICAL REFERENCE.\"" },
            { ((short)49, (short)0), "TOLD IN QUIET, HISSING\rSPEECH.\r\r\"THANK YOU FOR SAVING MY\rCHILDREN FROM THE MUTILATOR\rYARASH. IN RETURN I WILL\rAID YOU IN WHAT WAY I CAN,\rTHOUGH THAT MAY NOT BE\rGREAT." },
            { ((short)49, (short)1), "\r\"I HAVE LOST MUCH OF MY\rFOLLOWING TO YOUNG DRYTHH\rWHO LISTENS TO THE FALSE\rPROMISES OF TYRANTHRAXUS...\rTHAT IF HE BRINGS TROOPS TO\rINVADE PHLAN, HE WILL RULE\rTHE RIVERBANKS.\r" },
            { ((short)49, (short)2), "\"SO, DRYTHH AND HIS\rFOLLOWERS HAVE BEEN PROVING\rTHEMSELVES IN RAIDS UPON\rTHE KOBOLD CAVES TO THE\rSOUTHWEST AND THE HOBGOBLIN\rCAVES TO THE SOUTH.\r\r\"FOR SOME TIME MY FOLLOWERS\rHAVE BEEN DISAPPEARING." },
            { ((short)49, (short)3), "BUT, WHEN YOU FREED MY\rCHILDREN FROM THE CLUTCHES\rOF THE EVIL YARASH MY\rSTATUS WAS INCREASED.\rDRYTHH KEPT QUIET FOR A\rTIME, BUT ONCE AGAIN THE\rYOUNG WARRIORS LISTEN TO\rHIM AND NOT TO ME.\"" },
            { ((short)50, (short)0), "AN ANNOUNCEMENT ON RUGGED\rPAPER WRITTEN IN LARGE\rCLEAR SYMBOLS.\r\r\"BE IT ANNOUNCED THAT MACE,\rTHE FORMER CLERIC OF OUR\rLORD BANE, IS HEREBY\rEJECTED FROM THE CHURCH.\rHIS CRIMES INCLUDE REFUSAL" },
            { ((short)50, (short)1), "TO FOLLOW TEMPLE DICTATES,\rUNAUTHORIZED PERFORMANCE OF\rMAJOR MIRACLES, AND THE\rGREAT HERESY OF PLACING\rOTHER GODS ABOVE OUR\rALMIGHTY LORD BANE.\r\r\"ALL LOYAL FOLLOWERS OF\rLORD BANE MUST REPORT" },
            { ((short)50, (short)2), "MACE'S PRESENCE ON SIGHT.\rHE IS TO BE CAPTURED,\rBROUGHT BEFORE A LOYAL\rTRIBUNAL FOR FAIR AND JUST\rJUDGMENT, AND THEN BURNED\rAT THE STAKE.\"" },
        };

        public static short LineCount(short index)
        {
            short result;
            return LineCounts.TryGetValue(index, out result) ? result : (short)0;
        }

        public static string TextChunk(short index, short chunk)
        {
            string result;
            return Chunks.TryGetValue((index, chunk), out result) ? result : string.Empty;
        }
    }
}